I created auto retry mechanism by httpClient shim.

```typescript
class StripeHttpClient implements Stripe.HttpClient {
  baseHttpClient = Stripe.createNodeHttpClient();
  retryCounts: Record<string, number> = {};
  async makeRequest(
    host: string,
    port: string | number,
    path: string,
    method: 'GET' | 'POST' | 'PUT' | 'DELETE',
    headers: Record<string, string>,
    requestData: string | null,
    protocol: Stripe.HttpProtocol,
    timeout: number,
  ): Promise<Stripe.HttpClientResponse> {
    const originalIdempotencyKey = headers['Idempotency-Key'];
    let idempotencyKey: string | undefined;
    if (originalIdempotencyKey) {
      if (this.retryCounts[originalIdempotencyKey] !== undefined) {
        this.retryCounts[originalIdempotencyKey] = (this.retryCounts[originalIdempotencyKey] ?? 0) + 1;
        idempotencyKey = `${originalIdempotencyKey}-rate-limit-retry-${this.retryCounts[originalIdempotencyKey]}`;
      } else {
        this.retryCounts[originalIdempotencyKey] = 0;
        idempotencyKey = originalIdempotencyKey;
      }
    }

    const resp = await this.baseHttpClient.makeRequest(
      host,
      port,
      path,
      method,
      headers,
      requestData,
      protocol,
      timeout,
    );
    if (resp.getStatusCode() === 429) {
      console.log('retried');
      await new Promise(r => setTimeout(r, 500));
      return this.makeRequest(
        host,
        port,
        path,
        method,
        idempotencyKey ? { ...headers, 'Idempotency-Key': idempotencyKey } : headers,
        requestData,
        protocol,
        timeout,
      );
    }
    return resp;
  }
  getClientName() {
    return this.baseHttpClient.getClientName();
  }
}

const stripe = new Stripe('...', {
  apiVersion: '2020-08-27',
  maxNetworkRetries: 2,
  httpClient: new StripeHttpClient(),
});
```
