module.exports = function (options = {}) {
  // eslint-disable-line no-unused-vars
  return function stripeWebhookValidation(hook) {
    let stripeOptions = hook.app.get("stripe");
    const stripe = require("stripe")(stripeOptions.publicKey);
    const { GeneralError } = require("@feathersjs/errors");
    const endpointSecret = stripeOptions.customerEndpointSecret;
    const sig = hook.params.headers["stripe-signature"];
    try {
      //1st parameter of constructEvent need to be req.body
      stripe.webhooks.constructEvent(hook.data, sig, endpointSecret);
    } catch (err) {
      throw new GeneralError(
        `Error getting events -----------: ${err.message}`
      );
    }
    return Promise.resolve(hook);
  };
```

